// Pure traceability rules for French content against the derived DELF Prim word list (wordlist-fr.json, built by
// scripts/content/wordlist-fr.js). Vocabulary must be a word-list lemma at or below the pack's level (nouns with their
// article: "le chat", "l'école", "les yeux"); a phrase is checked word by word. Sentence words may be:
//   - forms of list lemmas at or below the level, generated by scripts/content/french.js: plurals and feminines
//     (agreement), present tense and imperative (all levels), past participles (passé composé: A2);
//   - other forms only when the papers attest that exact form at or below the level (j'aimerais, il était: A2);
//   - elisions l' j' m' t' d' n' qu' s' c' and contractions au aux du des of list lemmas;
//   - parts of multi-word list entries (s'il te plaît, parce que, il y a);
//   - numbers in the level's range (A1.1 ≤ 20, A1 ≤ 100) and names of the word list.
// Futur proche is aller (present) + infinitive and needs no rule.
import { CONTRACTIONS, ELISIONS, formsOf, LEVELS, norm, rank, tokenize } from './french.js';

export { LEVELS };
export const NUMBER_MAX = { 'A1.1': 20, A1: 100, A2: 100000, B1: Infinity, B2: Infinity };
/** Lowest level whose grammar allows a kind of generated form. Kinds missing here need an attested form. */
export const KIND_LEVEL = { base: 'A1.1', plural: 'A1.1', feminine: 'A1.1', present: 'A1.1', imperative: 'A1.1', participle: 'A2',
  imparfait: 'B1', futur: 'B1', conditionnel: 'B1', subjonctif: 'B1', gerondif: 'B1' };
const ARTICLE = /^(le|la|les|un|une|des)\s+|^l'/;

/** Index of wordlist-fr.json: form -> hits, lemma -> entries, multi-word entries, names. */
export function indexWordlistFr(json) {
  const forms = new Map();
  const lemmas = new Map();
  const multi = [];
  const add = (form, hit) => {
    if (!forms.has(form)) forms.set(form, []);
    forms.get(form).push(hit);
  };
  for (const e of json.entries) {
    const key = e.key ?? e.lemma;
    if (!lemmas.has(e.lemma)) lemmas.set(e.lemma, []);
    lemmas.get(e.lemma).push({ ...e, key });
    for (const [form, kind] of formsOf(e)) add(form, { key, kind, level: e.level });
    for (const [form, level] of Object.entries(e.forms || {})) {
      // an attested form counts from the level it was attested at, or the lemma's level if that is higher
      add(form, { key, kind: 'attested', level: rank(level) > rank(e.level) ? level : e.level });
    }
    const toks = tokenize(e.lemma).map((t) => t.word);
    if (toks.length > 1) multi.push({ key, tokens: toks, level: e.level });
  }
  multi.sort((a, b) => b.tokens.length - a.tokens.length);
  const names = new Map((json.names || []).map((n) => [n.name, n.level ?? 'A1.1']));
  return { forms, lemmas, multi, names };
}

const atOrBelow = (l, level) => rank(l) <= rank(level);
const lemmaOk = (index, lemma, level) => (index.lemmas.get(lemma) || []).some((e) => atOrBelow(e.level, level));

/** One token (lower-case word from tokenize) at a level. Returns { ok, how }. */
// allForms: a pack above its list (fr-b1: B1 grammar — imparfait, conditionnel, futur) accepts every form of a listed lemma
export function traceTokenFr(index, word, level, original = word, { allForms = false } = {}) {
  if (/^\d+$/.test(word)) return Number(word) <= NUMBER_MAX[level] ? { ok: true, how: 'number' } : { ok: false, how: 'number above level' };
  if (index.names.has(original)) return { ok: true, how: 'name' }; // a name of the list is usable at every level
  if (ELISIONS[word]) return lemmaOk(index, ELISIONS[word], level) ? { ok: true, how: `elision of ${ELISIONS[word]}` } : { ok: false, how: 'elided word above level' };
  if (CONTRACTIONS[word]) {
    const ok = CONTRACTIONS[word].every((l) => lemmaOk(index, l, level)) || (word === 'des' && lemmaOk(index, 'un', level));
    return ok ? { ok: true, how: 'contraction' } : { ok: false, how: 'contraction part above level' };
  }
  const hits = index.forms.get(word) || [];
  const good = hits.find((h) => atOrBelow(h.level, level) && (allForms || h.kind === 'attested' || (KIND_LEVEL[h.kind] && atOrBelow(KIND_LEVEL[h.kind], level))));
  if (good) return { ok: true, how: `${good.kind} of ${good.key}` };
  if (word.includes('-')) {
    const parts = word.split('-').filter((p) => p && p !== 't');
    if (parts.length > 1 && parts.every((p) => traceTokenFr(index, p, level, p, { allForms }).ok)) return { ok: true, how: 'hyphenated parts' };
  }
  if (hits.length) {
    const h = hits[0];
    if (!atOrBelow(h.level, level)) return { ok: false, how: `${h.key} is ${h.level}, above ${level}` };
    return { ok: false, how: `${h.kind} form of ${h.key} is not ${level} grammar (and not attested at ${level})` };
  }
  return { ok: false, how: 'not in the French word list' };
}

/** Untraceable words of a sentence at a level: [{ word, reason }]. */
export function traceSentenceFr(index, text, level, { allForms = false } = {}) {
  const toks = tokenize(text);
  const words = toks.map((t) => t.word);
  const covered = new Array(words.length).fill(false);
  for (const m of index.multi) {
    if (!atOrBelow(m.level, level)) continue;
    for (let i = 0; i + m.tokens.length <= words.length; i++) {
      // parts may be plural (des petits pois, les salles de bains)
      const same = (w, t) => w === t || ELISIONS[w] === t || w === `${t}s` || w === `${t}x`;
      if (m.tokens.every((t, k) => same(words[i + k], t))) for (let k = 0; k < m.tokens.length; k++) covered[i + k] = true;
    }
  }
  const problems = [];
  toks.forEach(({ word, original }, i) => {
    if (covered[i]) return;
    const r = traceTokenFr(index, word, level, original, { allForms });
    if (!r.ok) problems.push({ word: original, reason: r.how });
  });
  return problems;
}

/**
 * A vocabulary target: a list lemma at or below the level, nouns with an article ("le chat", "l'école", "les yeux");
 * otherwise a phrase whose words all trace. Returns { ok, reason?, key? } — key: the lemma it teaches (coverage).
 */
export function traceVocabFr(index, target, level) {
  const t = norm(target).trim();
  const rest = t.replace(ARTICLE, '');
  for (const cand of [t, rest]) {
    // with an article, the noun of two same-spelled lemmas (l'orange: the fruit, not the colour)
    const all = index.lemmas.get(cand) || [];
    // without one, the other (goûter: the verb; le goûter: the snack)
    const nounFirst = cand === rest && rest !== t;
    const entries = [...all.filter((e) => (e.pos === 'noun') === nounFirst), ...all.filter((e) => (e.pos === 'noun') !== nounFirst)];
    const ok = entries.find((e) => atOrBelow(e.level, level));
    if (ok) return { ok: true, key: ok.key, level: ok.level };
    if (entries.length) return { ok: false, reason: `${cand} is ${entries[0].level}, above ${level}` };
  }
  // a plural or feminine noun form with its article (les yeux, la copine is a lemma itself)
  const hit = (index.forms.get(rest) || []).find((h) => ['plural', 'feminine'].includes(h.kind));
  if (hit && !/\s/.test(rest)) {
    return atOrBelow(hit.level, level) ? { ok: true, key: hit.key, level: hit.level } : { ok: false, reason: `${hit.key} is ${hit.level}, above ${level}` };
  }
  const problems = traceSentenceFr(index, t, level);
  if (/[\s'-]/.test(t) && !problems.length) return { ok: true, key: null };
  return { ok: false, reason: problems.length ? problems.map((p) => `"${p.word}": ${p.reason}`).join('; ') : 'not a word-list lemma' };
}
